92|// The only text a scene route ships: this scene, its chapter, its pages,
93|// and neighbor ids for the pager. Throws on unknown scene id.
94|export function buildSceneView(
95|  model: ReaderModel,
96|  sceneId: string,
97|  budgetWords: number = PAGE_WORD_BUDGET,
