99|  const flat = model.chapters.flatMap((c) => c.scenes.map((s) => ({ ch: c.ch, chapterTitle: c.title, scene: s })));
100|  const at = flat.findIndex((e) => e.scene.id === sceneId);
101|  if (at < 0 || !flat[at]) throw new Error(`unknown scene ${sceneId}`);
102|  const entry = flat[at] as { ch: number; chapterTitle: string; scene: ReaderScene };
103|  const chapterScenes = flat.filter((e) => e.ch === entry.ch);
104|  const prev = at > 0 ? flat[at - 1] : null;
105|  const next = at < flat.length - 1 ? flat[at + 1] : null;
