141|
142|// Every pager move in one place: next/prev cross scenes and chapters,
143|// going back lands on the last sub-page, bounds are no-ops, unknown
144|// goto ids keep state.
145|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
146|  const at = index.order.indexOf(state.sceneId);
147|  if (at < 0) return state;
148|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
149|  if (action.kind === "next") {
150|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
151|    const nextId = index.order[at + 1];
152|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
153|  }
154|  if (action.kind === "prev") {
155|    if (state.page > 0) return { ...state, page: state.page - 1 };
156|    const prevId = at > 0 ? index.order[at - 1] : undefined;
157|    if (prevId === undefined) return state;
158|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
159|  }
160|  if (index.order.indexOf(action.sceneId) < 0) return state;
161|  const count = index.pageCounts.get(action.sceneId) ?? 1;
162|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
