190|// Throws on unordered scenes and on paragraphs covered zero or two times.
191|export function buildReaderModel(
192|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
193|  analysis: { scenes: AnalyzedScene[] },
194|): ReaderModel {
195|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
196|  const scenes = [...analysis.scenes];
197|  for (let i = 1; i < scenes.length; i++) {
198|    const prev = scenes[i - 1];
199|    const cur = scenes[i];
200|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
201|      throw new Error(`scenes out of order at ${cur.id}`);
202|    }
203|  }
204|  const seen = new Set<number>();
205|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
206|  for (const scene of scenes) {
207|    const paras: ReaderParagraph[] = [];
208|    for (let n = scene.start_n; n <= scene.end_n; n++) {
209|      const p = byN.get(n);
210|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
211|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
212|      seen.add(n);
213|      paras.push({ id: p.id, n: p.n, text: p.text });
214|    }
215|    sceneParagraphs.set(scene.id, paras);
216|  }
217|  if (seen.size !== book.paragraphs.length) {
218|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
219|  }
220|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
221|    const mine = scenes.filter((s) => s.ch === chapter.ch);
222|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
223|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
224|    }
225|    return {
226|      ch: chapter.ch,
227|      title: chapter.title,
228|      scenes: mine.map((s) => ({
229|        id: s.id,
230|        title: s.title,
231|        emotion: s.final === null ? null : { ...s.final },
232|        paragraphs: sceneParagraphs.get(s.id) ?? [],
233|      })),
234|    };
235|  });
236|  return {
237|    bookId: book.id,
238|    textVersion: book.textVersion,
239|    title: book.title,
240|    author: book.author,
241|    chapters,
242|  };
