1|// Scene isolation check: no scene route may ship another scene's text.
2|// Scans the prerendered HTML and RSC files of every scene route for
3|// excerpts of neighboring scenes' paragraphs. Run after `npm run build`.
4|// Fails when a neighbor excerpt appears, or when the scene's own text is
5|// missing from its HTML (which would prove the scan itself is blind).
6|import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
7|import { dirname, join } from "node:path";
8|import { fileURLToPath } from "node:url";
9|
10|const root = join(dirname(fileURLToPath(import.meta.url)), "..");
11|const EXCERPT_LEN = 80;
12|const MIN_EXCERPT_LEN = 40;
13|
14|export function unescapePayload(text) {
15|  return text
16|    .replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
17|    .replace(/\\[nrt]/g, "")
18|    .replace(/\\"/g, '"')
19|    .replace(/\\\\/g, "\\")
20|    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
21|    .replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(Number(dec)))
22|    .replace(/&quot;/g, '"')
23|    .replace(/&amp;/g, "&")
24|    .replace(/&lt;/g, "<")
25|    .replace(/&gt;/g, ">");
26|}
27|
28|// Lowercase alphanumeric only, so JSON/HTML escaping and whitespace
29|// differences cannot hide a leak.
30|export function normalize(text) {
31|  return unescapePayload(text)
32|    .toLowerCase()
33|    .replace(/[^\p{L}\p{N}]+/gu, "");
34|}
35|
36|export function excerpt(text) {
37|  return normalize(text).slice(0, EXCERPT_LEN);
38|}
39|
40|function loadScenes() {
41|  const book = JSON.parse(readFileSync(join(root, "data/books/oz/book.json"), "utf8"));
42|  const analysis = JSON.parse(readFileSync(join(root, "data/books/oz/analysis.json"), "utf8"));
43|  const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
44|  return analysis.scenes.map((scene) => ({
45|    id: scene.id,
46|    texts: Array.from({ length: scene.end_n - scene.start_n + 1 }, (_, i) => byN.get(scene.start_n + i) ?? ""),
47|  }));
48|}
49|
50|function routeFiles(sceneId) {
51|  const dir = join(root, ".next/server/app/leer");
52|  const names = existsSync(dir) ? readdirSync(dir) : [];
53|  const own = [`${sceneId}.html`, `${sceneId}.rsc`];
54|  const segments = names.filter((n) => n === `${sceneId}.segments`);
55|  const files = [];
56|  for (const name of own) {
57|    const path = join(dir, name);
58|    if (existsSync(path)) files.push(path);
59|  }
60|  for (const seg of segments) {
61|    for (const name of readdirSync(join(dir, seg))) {
62|      const path = join(dir, seg, name);
63|      if (statSync(path).isFile()) files.push(path);
64|    }
65|  }
66|  return files;
67|}
68|
69|export function checkIsolation({ scenes, readFile = (p) => readFileSync(p, "utf8"), filesFor = routeFiles } = {}) {
70|  const list = scenes ?? loadScenes();
71|  const failures = [];
72|  for (let i = 0; i < list.length; i++) {
73|    const scene = list[i];
74|    if (!scene) continue;
75|    const files = filesFor(scene.id);
76|    if (files.length === 0) {
77|      failures.push(`${scene.id}: no prerendered files (run npm run build first)`);
78|      continue;
79|    }
80|    // The scene's own first paragraph must be in the HTML itself, not
81|    // just the RSC payload: otherwise the scan is blind to an empty page.
82|    const html = files.filter((f) => f.endsWith(".html")).map((f) => normalize(readFile(f))).join("\n");
83|    const haystack = files.map((f) => normalize(readFile(f))).join("\n");
84|    const own = excerpt(scene.texts[0] ?? "");
85|    if (own.length >= MIN_EXCERPT_LEN && !html.includes(own)) {
86|      failures.push(`${scene.id}: own text missing from HTML, the scan is blind`);
87|    }
88|    for (const neighbor of [list[i - 1], list[i + 1]]) {
89|      if (!neighbor) continue;
90|      for (const text of neighbor.texts) {
91|        const probe = excerpt(text);
92|        if (probe.length < MIN_EXCERPT_LEN) continue;
93|        if (haystack.includes(probe)) {
94|          failures.push(`${scene.id}: leaks text of neighbor ${neighbor.id}`);
95|          break;
96|        }
97|      }
98|    }
99|  }
100|  return failures;
101|}
102|
103|if (process.argv[1] === fileURLToPath(import.meta.url)) {
104|  const failures = checkIsolation();
105|  if (failures.length > 0) {
106|    for (const failure of failures) console.error(`isolation: ${failure}`);
107|    process.exit(1);
108|  }
109|  console.log("isolation: every scene route carries only its own text");
