1|// Reader model: the slim shape the client receives. Joins paragraphs to
2|// scenes by ordinal range in reading order; analysis internals never leave.
3|import type { AnalyzedScene, Book } from "./types";
4|import type { Vector8 } from "./types";
5|
6|export interface ReaderParagraph {
7|  id: string;
8|  n: number;
9|  text: string;
10|}
11|
12|export interface ReaderScene {
13|  id: string;
14|  title: string;
15|  emotion: { vector: Vector8; intensity: number; tempo: number } | null;
16|  paragraphs: ReaderParagraph[];
17|}
18|
19|export interface ReaderChapter {
20|  ch: number;
21|  title: string;
22|  scenes: ReaderScene[];
23|}
24|
25|export interface ReaderModel {
26|  bookId: string;
27|  textVersion: string;
28|  title: string;
29|  author: string;
30|  chapters: ReaderChapter[];
31|}
32|
33|// 250 words fill a desktop view at the 65ch measure without scroll.
34|export const PAGE_WORD_BUDGET = 250;
35|
36|export interface SubPage {
37|  paragraphs: ReaderParagraph[];
38|  startN: number;
39|  endN: number;
40|  words: number;
41|}
42|
43|export function countWords(text: string): number {
44|  const words = text.split(/\s+/).filter((w) => w.length > 0);
45|  return words.length;
46|}
47|
48|// Split one scene into sub-pages by word budget at paragraph boundaries.
49|// A paragraph never splits; an oversize one takes its own page.
50|export function paginateScene(
51|  paragraphs: ReaderParagraph[],
52|  budgetWords: number = PAGE_WORD_BUDGET,
53|): SubPage[] {
54|  const pages: SubPage[] = [];
55|  let current: ReaderParagraph[] = [];
56|  let words = 0;
57|  const flush = () => {
58|    if (current.length === 0) return;
59|    pages.push({
60|      paragraphs: current,
61|      startN: current[0]?.n ?? 0,
62|      endN: current[current.length - 1]?.n ?? 0,
63|      words,
64|    });
65|    current = [];
66|    words = 0;
67|  };
68|  for (const p of paragraphs) {
69|    const w = countWords(p.text);
70|    if (current.length > 0 && words + w > budgetWords) flush();
71|    current.push(p);
72|    words += w;
73|  }
74|  flush();
75|  if (pages.length === 0) pages.push({ paragraphs: [], startN: 0, endN: 0, words: 0 });
76|  return pages;
77|}
78|
79|export interface SceneView {
80|  sceneId: string;
81|  ch: number;
82|  chapterTitle: string;
83|  title: string;
84|  emotion: ReaderScene["emotion"];
85|  pages: SubPage[];
86|  prevSceneId: string | null;
87|  nextSceneId: string | null;
88|  k: number;
89|  n: number;
90|}
91|
92|// The only text a scene route ships: this scene, its chapter, its pages,
93|// and neighbor ids for the pager. Throws on unknown scene id.
94|export function buildSceneView(
95|  model: ReaderModel,
96|  sceneId: string,
97|  budgetWords: number = PAGE_WORD_BUDGET,
98|): SceneView {
99|  const flat = model.chapters.flatMap((c) => c.scenes.map((s) => ({ ch: c.ch, chapterTitle: c.title, scene: s })));
100|  const at = flat.findIndex((e) => e.scene.id === sceneId);
101|  if (at < 0 || !flat[at]) throw new Error(`unknown scene ${sceneId}`);
102|  const entry = flat[at] as { ch: number; chapterTitle: string; scene: ReaderScene };
103|  const chapterScenes = flat.filter((e) => e.ch === entry.ch);
104|  const prev = at > 0 ? flat[at - 1] : null;
105|  const next = at < flat.length - 1 ? flat[at + 1] : null;
106|  return {
107|    sceneId,
108|    ch: entry.ch,
109|    chapterTitle: entry.chapterTitle,
110|    title: entry.scene.title,
111|    emotion: entry.scene.emotion,
112|    pages: paginateScene(entry.scene.paragraphs, budgetWords),
113|    prevSceneId: prev?.scene.id ?? null,
114|    nextSceneId: next?.scene.id ?? null,
115|    k: chapterScenes.findIndex((e) => e.scene.id === sceneId) + 1,
116|    n: chapterScenes.length,
117|  };
118|}
119|
120|export interface NavState {
121|  sceneId: string;
122|  page: number;
123|}
124|
125|export type NavAction =
126|  | { kind: "next" }
127|  | { kind: "prev" }
128|  | { kind: "goto"; sceneId: string; atEnd?: boolean };
129|
130|export interface NavIndex {
131|  order: string[];
132|  pageCounts: Map<string, number>;
133|}
134|
135|export function buildNavIndex(views: { sceneId: string; pages: number }[]): NavIndex {
136|  return {
137|    order: views.map((v) => v.sceneId),
138|    pageCounts: new Map(views.map((v) => [v.sceneId, v.pages] as [string, number])),
139|  };
140|}
141|
142|// Every pager move in one place: next/prev cross scenes and chapters,
143|// going back lands on the last sub-page, bounds are no-ops, unknown
144|// goto ids keep state.
145|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
146|  const at = index.order.indexOf(state.sceneId);
147|  if (at < 0) return state;
148|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
149|  if (action.kind === "next") {
150|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
151|    const nextId = index.order[at + 1];
152|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
153|  }
154|  if (action.kind === "prev") {
155|    if (state.page > 0) return { ...state, page: state.page - 1 };
156|    const prevId = at > 0 ? index.order[at - 1] : undefined;
157|    if (prevId === undefined) return state;
158|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
159|  }
160|  if (index.order.indexOf(action.sceneId) < 0) return state;
161|  const count = index.pageCounts.get(action.sceneId) ?? 1;
162|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
163|}
164|
165|// True only when the scene id changed. The container gates observeScene
166|// on this, so sub-page moves never touch the scheduler.
167|export function isSceneEntry(prevSceneId: string | null, nextSceneId: string): boolean {
168|  return prevSceneId !== nextSceneId;
169|}
170|
171|export interface SceneEntryGate {
172|  observedId: string | null;
173|  routeId: string | null;
174|  manifestReady: boolean;
175|}
176|
177|// The container's effect gate in one testable place: observe exactly once
178|// per route id, only after the manifest lands. Route params can lag a
179|// render, so the last observed id is compared before every observe call.
180|export function nextSceneEntry(gate: SceneEntryGate): {
181|  shouldObserve: boolean;
182|  nextObservedId: string | null;
183|} {
184|  if (!gate.routeId || !gate.manifestReady || !isSceneEntry(gate.observedId, gate.routeId)) {
185|    return { shouldObserve: false, nextObservedId: gate.observedId };
186|  }
187|  return { shouldObserve: true, nextObservedId: gate.routeId };
188|}
189|
190|// Throws on unordered scenes and on paragraphs covered zero or two times.
191|export function buildReaderModel(
192|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
193|  analysis: { scenes: AnalyzedScene[] },
194|): ReaderModel {
195|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
196|  const scenes = [...analysis.scenes];
197|  for (let i = 1; i < scenes.length; i++) {
198|    const prev = scenes[i - 1];
199|    const cur = scenes[i];
200|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
201|      throw new Error(`scenes out of order at ${cur.id}`);
202|    }
203|  }
204|  const seen = new Set<number>();
205|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
206|  for (const scene of scenes) {
207|    const paras: ReaderParagraph[] = [];
208|    for (let n = scene.start_n; n <= scene.end_n; n++) {
209|      const p = byN.get(n);
210|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
211|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
212|      seen.add(n);
213|      paras.push({ id: p.id, n: p.n, text: p.text });
214|    }
215|    sceneParagraphs.set(scene.id, paras);
216|  }
217|  if (seen.size !== book.paragraphs.length) {
218|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
219|  }
220|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
221|    const mine = scenes.filter((s) => s.ch === chapter.ch);
222|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
223|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
224|    }
225|    return {
226|      ch: chapter.ch,
227|      title: chapter.title,
228|      scenes: mine.map((s) => ({
229|        id: s.id,
230|        title: s.title,
231|        emotion: s.final === null ? null : { ...s.final },
232|        paragraphs: sceneParagraphs.get(s.id) ?? [],
233|      })),
234|    };
235|  });
236|  return {
237|    bookId: book.id,
238|    textVersion: book.textVersion,
239|    title: book.title,
240|    author: book.author,
241|    chapters,
242|  };
243|}

