1|"use client";
2|
3|import { useEffect, useMemo, useRef, useState } from "react";
4|import { useRouter } from "next/navigation";
5|import { buildNavIndex, navReducer } from "@/core/reader";
6|import type { NavAction, SceneView } from "@/core/reader";
7|
8|export interface ChapterJump {
9|  ch: number;
10|  title: string;
11|  firstSceneId: string;
12|}
13|
14|// One-shot entry intent: set just before pushing the previous scene
15|// route, so the new page opens on its last sub-page. Client memory only,
16|// never the URL, so prerendered pages stay static and a direct URL load
17|// always starts at page 0.
18|let enterAtEnd = false;
19|
20|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
21|// Sub-page moves stay in client state; scene moves push a new route.
22|export function ScenePage({
23|  view,
24|  chapters,
25|  views,
26|}: {
27|  view: SceneView;
28|  chapters: ChapterJump[];
29|  views: { sceneId: string; pages: number }[];
30|}) {
31|  const router = useRouter();
32|  const index = useMemo(() => buildNavIndex(views), [views]);
33|  const lastPage = view.pages.length - 1;
34|  const [page, setPage] = useState(() => {
35|    if (enterAtEnd) {
36|      enterAtEnd = false;
37|      return lastPage;
38|    }
39|    return 0;
40|  });
41|  const headingRef = useRef<HTMLHeadingElement>(null);
42|  const sub = view.pages[page] ?? view.pages[0];
43|  const atStart = view.prevSceneId === null && page === 0;
44|  const atBookEnd = view.nextSceneId === null && page === lastPage;
45|
46|  // Every pager move runs through navReducer; a new scene id means a
47|  // route push, a same-scene result means a client sub-page move.
48|  function move(action: NavAction) {
49|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
50|    if (next.sceneId !== view.sceneId) {
51|      if (next.page > 0) enterAtEnd = true;
52|      router.push(`/leer/${next.sceneId}`);
53|      return;
54|    }
55|    if (next.page !== page) {
56|      setPage(next.page);
57|      window.scrollTo(0, 0);
58|    }
59|  }
60|
61|  function goNext() {
62|    move({ kind: "next" });
63|  }
64|
65|  function goPrev() {
66|    move({ kind: "prev" });
67|  }
68|
69|  // Scene entry resets orientation; sub-page moves keep the heading.
70|  useEffect(() => {
71|    headingRef.current?.focus();
72|    window.scrollTo(0, 0);
73|  }, [view.sceneId]);
74|
75|  useEffect(() => {
76|    const onKey = (event: KeyboardEvent) => {
77|      if (event.metaKey || event.ctrlKey || event.altKey) return;
78|      const target = event.target as HTMLElement | null;
79|      if (
80|        target &&
81|        (target.tagName === "INPUT" ||
82|          target.tagName === "SELECT" ||
83|          target.tagName === "TEXTAREA" ||
84|          target.isContentEditable)
85|      ) {
86|        return;
87|      }
88|      if (event.key === "ArrowRight") {
89|        event.preventDefault();
90|        goNext();
91|      } else if (event.key === "ArrowLeft") {
92|        event.preventDefault();
93|        goPrev();
94|      }
95|    };
96|    window.addEventListener("keydown", onKey);
97|    return () => window.removeEventListener("keydown", onKey);
98|  }, [page, view.sceneId, index, router]);
99|
100|  function jumpChapter(ch: number) {
101|    const found = chapters.find((c) => c.ch === ch);
102|    if (found && found.firstSceneId !== view.sceneId) move({ kind: "goto", sceneId: found.firstSceneId });
103|  }
104|
105|  return (
106|    <article aria-labelledby="scene-heading">
107|      <div className="scene-view" key={`${view.sceneId}:${page}`}>
108|        <p className="scene-progress">
109|          Capítulo {view.ch}, {view.chapterTitle}. Escena {view.k} de {view.n}
110|          {view.pages.length > 1 ? ` Página ${page + 1} de ${view.pages.length}` : ""}
111|        </p>
112|        <h2 id="scene-heading" ref={headingRef} tabIndex={-1}>
113|          {view.title}
114|        </h2>
115|        {sub?.paragraphs.map((p) => (
116|          <p key={p.id} id={p.id} data-n={p.n}>
117|            {p.text}
118|          </p>
119|        ))}
120|      </div>
121|      <nav className="scene-nav" aria-label="Escenas">
122|        <button type="button" onClick={goPrev} disabled={atStart} aria-label="Anterior">
123|          Anterior
124|        </button>
125|        <button type="button" onClick={goNext} disabled={atBookEnd} aria-label="Siguiente">
126|          Siguiente
127|        </button>
128|        <label className="scene-jump">
129|          Capítulo
130|          <select value={view.ch} onChange={(e) => jumpChapter(Number(e.target.value))} aria-label="Capítulo">
131|            {chapters.map((c) => (
132|              <option key={c.ch} value={c.ch}>
133|                {c.ch}. {c.title}
134|              </option>
135|            ))}
136|          </select>
137|        </label>
138|      </nav>
139|    </article>
140|  );
141|}

