69|export function checkIsolation({ scenes, readFile = (p) => readFileSync(p, "utf8"), filesFor = routeFiles } = {}) {
70|  const list = scenes ?? loadScenes();
71|  const failures = [];
72|  for (let i = 0; i < list.length; i++) {
73|    const scene = list[i];
74|    if (!scene) continue;
75|    const files = filesFor(scene.id);
76|    if (files.length === 0) {
77|      failures.push(`${scene.id}: no prerendered files (run npm run build first)`);
78|      continue;
79|    }
80|    // The scene's own first paragraph must be in the HTML itself, not
81|    // just the RSC payload: otherwise the scan is blind to an empty page.
82|    const html = files.filter((f) => f.endsWith(".html")).map((f) => normalize(readFile(f))).join("\n");
83|    const haystack = files.map((f) => normalize(readFile(f))).join("\n");
84|    const own = excerpt(scene.texts[0] ?? "");
85|    if (own.length >= MIN_EXCERPT_LEN && !html.includes(own)) {
86|      failures.push(`${scene.id}: own text missing from HTML, the scan is blind`);
87|    }
88|    for (const neighbor of [list[i - 1], list[i + 1]]) {
89|      if (!neighbor) continue;
90|      for (const text of neighbor.texts) {
91|        const probe = excerpt(text);
92|        if (probe.length < MIN_EXCERPT_LEN) continue;
93|        if (haystack.includes(probe)) {
94|          failures.push(`${scene.id}: leaks text of neighbor ${neighbor.id}`);
95|          break;
96|        }
97|      }
98|    }
99|  }
100|  return failures;
101|}
102|
103|if (process.argv[1] === fileURLToPath(import.meta.url)) {
104|  const failures = checkIsolation();
105|  if (failures.length > 0) {
106|    for (const failure of failures) console.error(`isolation: ${failure}`);
107|    process.exit(1);
108|  }
109|  console.log("isolation: every scene route carries only its own text");
